from __future__ import annotations

import os
import unittest
from pathlib import Path
from tempfile import TemporaryDirectory
from unittest.mock import patch

from agent.database_server import (
    AUDIT_LOG_ROTATED_RE,
    AUDIT_LOG_STAGED_RE,
    DatabaseServer,
    list_audit_logs,
    parse_audit_log_time_range,
)

RECORD = "20250811 12:00:{second},dbserver,root,localhost,42,1337,QUERY,mydb,'select 1',0\n"


def write(path: Path, content: str) -> str:
    path.write_text(content)
    return str(path)


class TestParseAuditLogTimeRange(unittest.TestCase):
    def setUp(self):
        self.directory = TemporaryDirectory()
        self.path = Path(self.directory.name)

    def tearDown(self):
        self.directory.cleanup()

    def test_returns_first_and_last_record_timestamps(self):
        log = write(
            self.path / "audit.log",
            RECORD.format(second="01") + RECORD.format(second="02") + RECORD.format(second="03"),
        )

        self.assertEqual(
            parse_audit_log_time_range(log),
            ("2025-08-11T12:00:01", "2025-08-11T12:00:03"),
        )

    def test_ignores_continuation_lines_of_a_query_containing_newlines(self):
        log = write(
            self.path / "audit.log",
            RECORD.format(second="01")
            + "20250811 12:00:05,dbserver,root,localhost,42,1338,QUERY,mydb,'select\n"
            + "1 from t',0\n",
        )

        # The trailing "1 from t',0" line is part of the previous record, so the end of
        # the range is 12:00:05 and not something parsed out of that fragment.
        self.assertEqual(
            parse_audit_log_time_range(log),
            ("2025-08-11T12:00:01", "2025-08-11T12:00:05"),
        )

    def test_returns_none_for_an_empty_file(self):
        self.assertEqual(parse_audit_log_time_range(write(self.path / "audit.log", "")), (None, None))

    def test_returns_none_when_no_line_looks_like_a_record(self):
        log = write(self.path / "audit.log", "not an audit record\nnor is this\n")

        self.assertEqual(parse_audit_log_time_range(log), (None, None))


class TestListAuditLogs(unittest.TestCase):
    def setUp(self):
        self.directory = TemporaryDirectory()
        self.path = Path(self.directory.name)

    def tearDown(self):
        self.directory.cleanup()

    def test_lists_only_rotated_logs_sorted_by_name(self):
        for name in ["server_audit.log", "server_audit.log.2", "server_audit.log.1", "mysql-error.log"]:
            write(self.path / name, "")

        # The live server_audit.log is excluded: the plugin still holds it open.
        self.assertEqual(
            [log["name"] for log in list_audit_logs(str(self.path), AUDIT_LOG_ROTATED_RE)],
            ["server_audit.log.1", "server_audit.log.2"],
        )

    def test_returns_empty_list_when_directory_is_missing(self):
        self.assertEqual(list_audit_logs(str(self.path / "nope"), AUDIT_LOG_ROTATED_RE), [])


class TestStageAuditLogs(unittest.TestCase):
    def setUp(self):
        self.directory = TemporaryDirectory()
        self.server = DatabaseServer.__new__(DatabaseServer)
        self.server.audit_log_directory = self.directory.name
        self.server.audit_log_pending_directory = os.path.join(self.directory.name, "audit_pending")

    def tearDown(self):
        self.directory.cleanup()

    def stage(self):
        # Only the MariaDB connection is mocked; the file moves are real.
        with patch("agent.database_server.Database") as db, patch.object(DatabaseServer, "db_port", 3306):
            self.queries = db.return_value.execute_query
            self.queries.return_value = (True, [{"output": {"data": [[9]]}}])
            return DatabaseServer.stage_audit_logs.__wrapped__(self.server, "127.0.0.1", "password")

    def executed(self):
        return [call.args[0] for call in self.queries.call_args_list]

    def test_rotations_are_frozen_while_the_files_are_moved_and_restored_after(self):
        # A rotation midway renumbers every file, and left at 0 the log never rotates again
        write(Path(self.directory.name) / "server_audit.log.1", RECORD.format(second="01"))

        self.stage()

        self.assertEqual(
            self.executed()[1:],
            [
                "SET GLOBAL server_audit_file_rotate_now = 1;",
                "SET GLOBAL server_audit_file_rotations = 0;",
                "SET GLOBAL server_audit_file_rotations = 9;",
            ],
        )

    def test_rotations_are_restored_even_when_staging_blows_up(self):
        write(Path(self.directory.name) / "server_audit.log.1", RECORD.format(second="01"))

        with patch.object(DatabaseServer, "move_rotated_audit_logs_to_pending", side_effect=OSError):
            self.assertRaises(OSError, self.stage)

        self.assertEqual(self.executed()[-1], "SET GLOBAL server_audit_file_rotations = 9;")

    def test_moves_rotated_logs_out_of_the_plugin_namespace(self):
        for name in ["server_audit.log", "server_audit.log.1", "server_audit.log.2"]:
            write(Path(self.directory.name) / name, RECORD.format(second="01"))

        staged = self.stage()["staged_files"]

        self.assertEqual(len(staged), 2)
        for name in staged:
            self.assertRegex(name, AUDIT_LOG_STAGED_RE)
        # Nothing rotated is left behind for the next rotation to renumber
        self.assertEqual(list_audit_logs(self.directory.name, AUDIT_LOG_ROTATED_RE), [])
        # The live log the plugin is writing to is untouched
        self.assertTrue((Path(self.directory.name) / "server_audit.log").exists())

    def test_refuses_to_overwrite_an_already_staged_log(self):
        source = Path(self.directory.name) / "server_audit.log.1"
        write(source, RECORD.format(second="01"))
        os.makedirs(self.server.audit_log_pending_directory)

        [staged] = self.stage()["staged_files"]
        write(source, RECORD.format(second="02"))
        os.utime(source, (0, os.stat(Path(self.server.audit_log_pending_directory) / staged).st_mtime))

        with self.assertRaises(FileExistsError):
            self.stage()

        # os.rename would have clobbered the earlier log silently; it is still intact
        self.assertTrue(source.exists())
        self.assertEqual(
            (Path(self.server.audit_log_pending_directory) / staged).read_text(),
            RECORD.format(second="01"),
        )


class TestAuditLogLock(unittest.TestCase):
    def setUp(self):
        self.directory = TemporaryDirectory()
        self.server = DatabaseServer.__new__(DatabaseServer)
        self.server.audit_log_pending_directory = os.path.join(self.directory.name, "audit_pending")

    def tearDown(self):
        self.directory.cleanup()

    def acquire(self):
        with self.server.audit_log_lock():
            pass

    def test_a_second_run_is_refused_while_the_first_holds_the_lock(self):
        # Overlapping runs rotate and unlink under each other, which loses audit logs
        with self.server.audit_log_lock():
            self.assertRaisesRegex(Exception, "already running", self.acquire)

    def test_the_lock_is_released_when_a_run_fails(self):
        with self.assertRaises(OSError), self.server.audit_log_lock():
            raise OSError

        self.acquire()

"""Backup Site jobs read back out of the agent's job database.

Press keeps its own Site Backup records, but a site that has moved between servers
leaves its older jobs behind on the server it ran them on. This is how those are
read back, per site and bounded to a date range.

The parsing mirrors frappe/fc-scripts/create_backup_log.py, which does the same
thing by opening jobs.sqlite3 directly.
"""

from __future__ import annotations

import json
import re
from datetime import datetime, timedelta

from agent.job import JobModel, StepModel

JOB_NAME = "Backup Site"
UPLOAD_STEP = "Upload Site Backup to S3"

# An audit asks about a year at a time, and the cap keeps one call from walking the
# whole job database
MAX_RANGE_DAYS = 366
MAX_JOBS = 2000

ARTIFACTS = ("database", "public", "private", "site_config")

# Backups live at <bench>/sites/<site>/private/backups/, and their url is the site itself
SITE_FROM_PATH = re.compile(r"(?:/sites/|^\./)([^/]+)/private/backups/")
SITE_FROM_URL = re.compile(r"^https?://([^/]+)/")

# "FileNotFoundError: [Errno 2] ...", "subprocess.CalledProcessError: ..."
EXCEPTION_LINE = re.compile(r"^(?:[A-Za-z_][\w.]*\.)?[A-Z]\w*(?:Error|Exception|Exit|Interrupt|Warning)\b.*")

TRACEBACK_NOISE = ('File "', "Traceback", "^", "~", "During handling", "The above exception")


class InvalidRange(Exception):
    """The caller asked for a range that cannot be served."""


def get_backup_jobs(site: str, start: str, end: str) -> dict:
    """Every Backup Site job this server ran for one site, newest first."""
    start_at, end_at = parse_range(start, end)

    query = (
        JobModel.select()
        .where(
            (JobModel.name == JOB_NAME)
            & matches_site(site)
            & (JobModel.start >= start_at)
            & (JobModel.start < end_at)
        )
        .order_by(JobModel.id.desc())
        # One over the cap, so a full page can be told apart from an exact fit
        .limit(MAX_JOBS + 1)
    )

    jobs = list(query)
    truncated = len(jobs) > MAX_JOBS
    jobs = jobs[:MAX_JOBS]

    steps = steps_of(jobs)
    return {
        "jobs": [
            summarise(job, steps.get(job.id, []))
            for job in jobs
            # site_of still decides, in case a LIKE wildcard widened the match
            if site_of(load_json(job.data), steps.get(job.id, [])) == site
        ],
        # Says so rather than quietly dropping the oldest days in the range
        "truncated": truncated,
    }


def matches_site(site: str):
    """Match the site's own backup paths.

    Anchored on the separators around the name, so a site whose name merely contains
    this one cannot match and eat the row limit before the exact filter runs.
    """
    return JobModel.data.contains(f"/{site}/private/backups/") | JobModel.data.contains(f"://{site}/backups/")


def parse_range(start: str, end: str) -> tuple[datetime, datetime]:
    """Both ends as datetimes, with end pushed to the following midnight so it counts."""
    try:
        start_at = datetime.strptime(start, "%Y-%m-%d")
        end_at = datetime.strptime(end, "%Y-%m-%d")
    except (TypeError, ValueError):
        raise InvalidRange("start and end must be dates formatted YYYY-MM-DD")

    if start_at > end_at:
        raise InvalidRange("start must be on or before end")
    if (end_at - start_at).days >= MAX_RANGE_DAYS:
        raise InvalidRange(f"range must be {MAX_RANGE_DAYS} days or less")

    return start_at, end_at + timedelta(days=1)


def steps_of(jobs: list[JobModel]) -> dict[int, list[tuple]]:
    if not jobs:
        return {}

    steps: dict[int, list[tuple]] = {}
    query = StepModel.select(StepModel.job, StepModel.name, StepModel.status, StepModel.data).where(
        StepModel.job << [job.id for job in jobs]
    )
    for step in query.order_by(StepModel.id):
        steps.setdefault(step.job_id, []).append((step.name, step.status, load_json(step.data)))
    return steps


def summarise(job: JobModel, steps: list[tuple]) -> dict:
    data = load_json(job.data)
    backups = data.get("backups") if isinstance(data, dict) else None

    return {
        "id": job.id,
        "agent_job_id": job.agent_job_id,
        "status": job.status,
        "type": backup_type(job.status, data, steps),
        "start": str(job.start) if job.start else None,
        "end": str(job.end) if job.end else None,
        "duration": str(job.duration) if job.duration else None,
        "sizes": {artifact: size_of(backups, artifact) for artifact in ARTIFACTS},
        # Only the one interpreted line, never the raw traceback
        "failure_reason": failure_reason(data, steps) if job.status != "Success" else "",
    }


def site_of(data: dict | None, steps: list[tuple]) -> str | None:
    """The site a job ran for, read off its backup paths.

    Deliberately not read from the bench command: that is caller-supplied text, and a
    path under the site's own backup directory is the agent's own record of the run.
    """
    backups = data.get("backups") if isinstance(data, dict) else None
    if not isinstance(backups, dict):
        return None

    for entry in backups.values():
        if not isinstance(entry, dict):
            continue
        match = SITE_FROM_PATH.search(entry.get("path") or "")
        if match:
            return match.group(1)
        match = SITE_FROM_URL.match(entry.get("url") or "")
        if match:
            return match.group(1)
    return None


def backup_type(status: str, data: dict | None, steps: list[tuple]) -> str:
    if status != "Success":
        return ""
    if isinstance(data, dict) and data.get("offsite"):
        return "offsite"
    for step_name, step_status, _ in steps:
        if step_name == UPLOAD_STEP and step_status == "Success":
            return "offsite"
    return "onsite"


def size_of(backups: dict | None, artifact: str) -> int:
    entry = (backups or {}).get(artifact)
    if isinstance(entry, dict) and isinstance(entry.get("size"), int):
        return entry["size"]
    return 0


def failure_reason(data: dict | None, steps: list[tuple]) -> str:
    """Why a backup failed, preferring the innermost python exception.

    The step traceback is usually the agent-side CalledProcessError wrapper, while the
    real cause is the last exception in the command output.
    """
    sources = [
        (step_data.get("output"), step_data.get("traceback"))
        for _, step_status, step_data in steps
        if step_status != "Success" and isinstance(step_data, dict)
    ]
    if isinstance(data, dict) and "output" in data:
        sources.append((data.get("output"), data.get("traceback")))

    for output, tb in sources:
        reason = exception_line(output) or exception_line(tb)
        if reason:
            return reason
    for output, tb in sources:
        reason = last_meaningful_line(output) or last_meaningful_line(tb)
        if reason:
            return reason
    return ""


def exception_line(text: str | None) -> str | None:
    for line in meaningful_lines(text):
        if EXCEPTION_LINE.match(line):
            return line
    return None


def last_meaningful_line(text: str | None) -> str | None:
    for line in meaningful_lines(text):
        return line
    return None


def meaningful_lines(text: str | None):
    for line in reversed((text or "").splitlines()):
        line = line.strip()
        if line and not line.startswith(TRACEBACK_NOISE):
            yield line


def load_json(raw: str | None):
    if not raw:
        return None
    try:
        return json.loads(raw)
    except (ValueError, TypeError):
        return None

"""Basic DB optimizer for Frappe Framework based app.

This is largely based on heuristics and known good practices for indexing.
"""

from __future__ import annotations

import re
from collections import defaultdict
from dataclasses import dataclass
from typing import TYPE_CHECKING, Literal

from sql_metadata import Parser

if TYPE_CHECKING:
    from agent.site import Site

# Any index that reads more than 30% table on average is not "useful"
INDEX_SCORE_THRESHOLD = 0.3
# Anything reading less than this percent of table is considered optimal
OPTIMIZATION_THRESHOLD = 0.1


def cstr(data: str | None) -> str:
    if data is None:
        return ""
    return str(data)


def cint(data: int | str | float | None) -> int:
    if data is None:
        return 0
    if isinstance(data, str):
        if len(data) == 0:
            return 0
        data = data.split(".")[0]  # remove decimals
        data = data.replace(",", "")
    return int(data)


def flt(data: float | None) -> float:
    if data is None:
        return 0.0
    return float(data)


@dataclass
class DBExplain:
    # refer: https://mariadb.com/kb/en/explain/
    # Anything not explicitly encoded here is likely not supported.
    select_type: Literal["SIMPLE", "PRIMARY", "SUBQUERY", "UNION", "DERIVED"]
    table: str
    scan_type: Literal[  # What type of scan will be performed
        "ALL",  # Full table scan
        "CONST",  # Single row will be read
        "EQ_REF",  # A single row is found from *unique* index
        "REF",  # Index is used, but MIGHT hit more than 1 rows as it's non-unique
        "RANGE",  # The table will be accessed with a key over one or more value ranges.
        "INDEX_MERGE",  # multiple indexes are used and merged smartly. Equivalent to RANGE
        "INDEX_SUBQUERY",
        "INDEX",  # Full index scan is performed. Similar to full table scan in case of large number of rows.
        "REF_OR_NULL",
        "UNIQUE_SUBQUERY",
        "FULLTEXT",  # Full text index is used,
    ]
    possible_keys: list[str] | None = None  # possible indexes that can be used
    key: str | None = None  # This index is being used
    key_len: int | None = None  # How many prefix bytes from index are being used
    ref: str | None = None  # is reference constant or some other column
    rows: int = 0  # roughly how many rows will be examined
    extra: str | None = None

    @classmethod
    def from_frappe_output(cls, data) -> DBExplain:
        return cls(
            select_type=cstr(data["select_type"]).upper(),
            table=data["table"],
            scan_type=cstr(data["type"]).upper(),
            possible_keys=data["possible_keys"],
            key=data["key"],
            key_len=cint(data["key_len"]) if data["key_len"] else None,
            ref=data["ref"],
            rows=cint(data["rows"]),
            extra=data.get("Extra"),
        )


@dataclass
class DBColumn:
    name: str
    cardinality: int | None
    is_nullable: bool
    default: str
    data_type: str

    @classmethod
    def from_frappe_output(cls, data) -> DBColumn:
        "Parse DBColumn from output of describe-database-table command in Frappe"
        return cls(
            name=data["column"],
            cardinality=data.get("cardinality"),
            is_nullable=data["is_nullable"],
            default=data["default"],
            data_type=data["type"],
        )


@dataclass
class DBIndex:
    name: str
    column: str
    table: str
    unique: bool | None = None
    cardinality: int | None = None
    sequence: int = 1
    nullable: bool = True
    _score: float = 0.0

    def __eq__(self, other: DBIndex) -> bool:
        return self.column == other.column and self.sequence == other.sequence and self.table == other.table

    def __repr__(self):
        return f"DBIndex(`{self.table}`.`{self.column}`)"

    @classmethod
    def from_frappe_output(cls, data, table) -> DBIndex:
        "Parse DBIndex from output of describe-database-table command in Frappe"
        return cls(
            name=data["name"],
            table=table,
            unique=data["unique"],
            cardinality=data["cardinality"],
            sequence=data["sequence"],
            nullable=data["nullable"],
            column=data["column"],
        )

    def to_dict(self, fields: list[str] | None = None) -> dict:
        if not fields:
            fields = ["name", "column", "table", "unique", "cardinality", "sequence", "nullable"]
        return {field: getattr(self, field) for field in fields}


@dataclass
class ColumnStat:
    column_name: str
    avg_frequency: float
    avg_length: float
    nulls_ratio: float | None = None
    histogram: list[float] = None

    def __post_init__(self):
        if not self.histogram:
            self.histogram = []

    @classmethod
    def from_frappe_output(cls, data) -> ColumnStat:
        return cls(
            column_name=data["column_name"],
            avg_frequency=data["avg_frequency"],
            avg_length=data["avg_length"],
            nulls_ratio=data["nulls_ratio"],
            histogram=[flt(bin) for bin in data["histogram"].split(",")] if data["histogram"] else [],
        )


@dataclass
class DBTable:
    name: str
    total_rows: int
    schema: list[DBColumn] | None = None
    indexes: list[DBIndex] | None = None

    def __post_init__(self):
        if not self.schema:
            self.schema = []
        if not self.indexes:
            self.indexes = []

    def update_cardinality(self, column_stats: list[ColumnStat]) -> None:
        """Estimate cardinality using mysql.column_stat"""
        for column_stat in column_stats:
            for col in self.schema:
                if col.name == column_stat.column_name and not col.cardinality and column_stat.avg_frequency:
                    # "hack" or "math" - average frequency is on average how frequently a row value appears.
                    # Avg = total_rows / cardinality, so...
                    col.cardinality = self.total_rows / column_stat.avg_frequency

    @classmethod
    def from_frappe_output(cls, data) -> DBTable:
        "Parse DBTable from output of describe-database-table command in Frappe"
        table_name = data["table_name"]
        return cls(
            name=table_name,
            total_rows=data["total_rows"],
            schema=[DBColumn.from_frappe_output(c) for c in data["schema"]],
            indexes=[DBIndex.from_frappe_output(i, table_name) for i in data["indexes"]],
        )

    def has_column(self, column: str) -> bool:
        return any(col.name == column for col in self.schema)


@dataclass
class DBOptimizer:
    query: str  # raw query in string format
    explain_plan: list[DBExplain] = None
    tables: dict[str, DBTable] = None
    parsed_query: Parser = None

    def __post_init__(self):
        if not self.explain_plan:
            self.explain_plan = []
        if not self.tables:
            self.tables = {}
        for explain_entry in self.explain_plan:
            explain_entry.select_type = explain_entry.select_type.upper()
            explain_entry.scan_type = explain_entry.scan_type.upper()
        self.parsed_query = Parser(re.sub(r'"(\S+)"', r"'\1'", self.query))

    @property
    def tables_examined(self) -> list[str]:
        return self.parsed_query.tables

    def update_table_data(self, table: DBTable):
        self.tables[table.name] = table

    def potential_indexes(self) -> list[DBIndex]:
        """Get all columns that can potentially be indexed to speed up this query."""

        possible_indexes = []

        # Where claus columns using these operators benefit from index
        #  1. = (equality)
        #  2. >, <, >=, <=
        #  3. LIKE 'xyz%' (Prefix search)
        #  4. BETWEEN (for date[time] fields)
        #  5. IN (similar to equality)
        if where_columns := self.parsed_query.columns_dict.get("where"):
            # TODO: Apply some heuristics here, not all columns in where clause are actually useful
            possible_indexes.extend(where_columns)

        # Join clauses - Both sides of join should ideally be indexed. One will *usually* be primary key.
        if join_columns := self.parsed_query.columns_dict.get("join"):
            possible_indexes.extend(join_columns)

        # Top N query variant - Order by column can possibly speed up the query
        if (
            order_by_columns := self.parsed_query.columns_dict.get("order_by")
        ) and self.parsed_query.limit_and_offset:
            possible_indexes.extend(order_by_columns)

        possible_db_indexes = [self._convert_to_db_index(i) for i in possible_indexes]
        possible_db_indexes = [i for i in possible_db_indexes if i.column not in ("*", "name")]
        possible_db_indexes.sort(key=lambda i: (i.table, i.column))

        return self._remove_existing_indexes(possible_db_indexes)

    def _convert_to_db_index(self, column: str) -> DBIndex:
        column_name, table = None, None

        if "." in column:
            table, column_name = column.split(".")
        else:
            column_name = column
            for table_name, db_table in self.tables.items():
                if db_table.has_column(column):
                    table = table_name
                    break
        return DBIndex(column=column_name, name=column_name, table=table)

    def _remove_existing_indexes(self, potential_indexes: list[DBIndex]) -> list[DBIndex]:  # noqa: C901
        """Given list of potential index candidates remove the ones that already exist.

        This also removes multi-column indexes for parts that are applicable to query.
        Example: If multi-col index A+B+C exists and query utilizes A+B then
        A+B are removed from potential indexes.
        """

        def remove_maximum_indexes(idx: list[DBIndex]):
            """Try to remove entire index from potential indexes
            If not possible, reduce one part and try again until no parts are left.
            """
            if not idx:
                return None
            matched_sub_index = []
            for idx_part in list(idx):
                matching_part = [
                    i for i in potential_indexes if i.column == idx_part.column and i.table == idx_part.table
                ]
                if not matching_part:
                    # pop and recurse
                    idx.pop()
                    return remove_maximum_indexes(idx)
                matched_sub_index.extend(matching_part)

            # Every part matched now, lets remove those parts
            for i in matched_sub_index:
                potential_indexes.remove(i)
            return None

        # Reconstruct multi-col index
        for table in self.tables.values():
            merged_indexes = defaultdict(list)
            for index in table.indexes:
                merged_indexes[index.name].append(index)

            for idx in merged_indexes.values():
                idx.sort(key=lambda x: x.sequence)

            for idx in merged_indexes.values():
                remove_maximum_indexes(idx)
        return potential_indexes

    def suggest_index(self) -> DBIndex | None:
        """Suggest best possible column to index given query and table stats."""
        if missing_tables := (set(self.tables_examined) - set(self.tables.keys())):
            raise Exception("DBTable information missing for: " + ", ".join(missing_tables))

        potential_indexes = self.potential_indexes()

        for index in list(potential_indexes):
            table = self.tables[index.table]

            # Data type is not easily indexable - skip
            column = next(c for c in table.schema if c.name == index.column)
            if "text" in column.data_type.lower() or "json" in column.data_type.lower():
                potential_indexes.remove(index)
            # Update cardinality from column so scoring can be done
            index.cardinality = column.cardinality

        for index in potential_indexes:
            index._score = self.index_score(index)

        potential_indexes.sort(key=lambda i: i._score)
        if (
            potential_indexes
            and (best_index := potential_indexes[0])
            and best_index._score < INDEX_SCORE_THRESHOLD
        ):
            return best_index
        return None

    def index_score(self, index: DBIndex) -> float:
        """Score an index from 0 to 1 based on usefulness.

        A score of 0.5 indicates on average this index will read 50% of the table. (e.g. checkboxes)"""
        table = self.tables[index.table]

        cardinality = index.cardinality or 2
        total_rows = table.total_rows or cardinality or 1

        # We assume most unique values are evenly distributed, this is
        # definitely not the case IRL but it should be good enough assumptions
        # Score is roughly what percentage of table we will end up reading on typical query
        rows_fetched_on_average = (table.total_rows or cardinality) / cardinality
        return rows_fetched_on_average / total_rows

    def can_be_optimized(self) -> bool:
        """Return true if it's worth optimizing.

        Few cases can not be optimized any further. E.g. ref/eq_ref/cost type
        of queries. Assume that anything that reads <10% of table already is
        not possible to truly optimize with these heuristics."""
        for explain in self.explain_plan:
            for table in self.tables.values():
                if table.name != explain.table:
                    continue
                if (explain.rows / table.total_rows) > OPTIMIZATION_THRESHOLD:
                    return True
        return False


class OptimizeDatabaseQueries:
    def __init__(self, site: Site, queries: list[str], database_root_password: str):
        self.site = site
        self.database_root_password = [REDACTED]
        self.queries = queries
        self.table_cache: dict[str, DBTable] = {}
        self.column_statistics_cache: dict[str, list[ColumnStat]] = {}

    def analyze(self) -> dict[str, list[DBIndex]] | None:
        # generate explain output for all the queries at once
        explain_output_of_queries_result = self.site.db_instance().explain_queries(self.queries)
        explain_output_of_queries = {}
        for query, explain_output in explain_output_of_queries_result.items():
            explain_output_of_queries[query] = [DBExplain.from_frappe_output(e) for e in explain_output]

        suggested_indexes_of_queries = {}

        for query in self.queries:
            if query not in explain_output_of_queries:
                continue
            explain_output = explain_output_of_queries[query]
            optimizer = DBOptimizer(query=query, explain_plan=explain_output)
            tables = optimizer.tables_examined

            for table in tables:
                db_table = self.describe_database_table(table)
                column_stats = self.fetch_column_stats(table)
                db_table.update_cardinality(column_stats)
                optimizer.update_table_data(db_table)

            index = optimizer.suggest_index()
            if index:
                if query not in suggested_indexes_of_queries:
                    suggested_indexes_of_queries[query] = []
                suggested_indexes_of_queries[query].append(index)

        return suggested_indexes_of_queries

    def describe_database_table(self, table_name: str) -> DBTable | None:
        if table_name in self.table_cache:
            return self.table_cache[table_name]
        result = self.site.describe_database_table(table_name)
        if result is None:
            self.table_cache[table_name] = None
            return None
        table = DBTable.from_frappe_output(result)
        self.table_cache[table_name] = table
        return table

    def fetch_column_stats(self, table_name: str) -> list[ColumnStat] | None:
        if table_name in self.column_statistics_cache:
            return self.column_statistics_cache[table_name]
        db = self.site.db_instance("root", self.database_root_password)
        return db.fetch_database_column_statistics(table_name)

